COMMENT ON TABLE "propriedade" IS 'Raiz do isolamento de dados (RNF05, RN31). Guarda o titular (dono real, que pode nem usar o sistema), quem cadastrou e os parâmetros configuráveis.';

COMMENT ON COLUMN "propriedade"."titular_nome" IS 'nome do dono real (pode listar mais de um proprietário); sem CPF/CNPJ no MVP (RN35)';

