COMMENT ON COLUMN "propriedade"."rendimento_carcaca_pct" IS 'RN18. Valor provisório, a validar com o produtor';

COMMENT ON COLUMN "propriedade"."praca_padrao" IS 'RN27';

COMMENT ON COLUMN "propriedade"."dias_alerta_vencimento" IS 'RN13';

COMMENT ON COLUMN "propriedade"."ativa" IS 'inativação da propriedade (RN37), em vez de exclusão (A2)';

COMMENT ON TABLE "usuario" IS 'RF01. A ligação com propriedades é feita em usuario_propriedade (N:N).';

COMMENT ON COLUMN "usuario"."senha_hash" IS 'hash seguro (RNF04)';

COMMENT ON TABLE "usuario_propriedade" IS 'RF01, RF32, RF35, RN31, RN35. Um usuário pode pertencer a várias propriedades e uma propriedade pode ter vários usuários. O papel (proprietário ou gestor) fica no vínculo; um papel de desenvolvedor/administrador do sistema, no futuro, será atributo do usuário.';

COMMENT ON COLUMN "usuario_propriedade"."papel" IS 'proprietario | gestor. Papel declarado pelo usuário nesta propriedade (RN35)';

COMMENT ON COLUMN "usuario_propriedade"."aceite_declaracao_em" IS 'data do aceite do termo de declaração';

COMMENT ON COLUMN "usuario_propriedade"."versao_termo" IS 'versão do texto do termo aceito';

COMMENT ON TABLE "convite_propriedade" IS 'RF34, RF35, RN39. Convite por link de uso único, com validade.';

COMMENT ON COLUMN "convite_propriedade"."papel" IS 'proprietario | gestor. Papel definido por quem convida';

COMMENT ON COLUMN "convite_propriedade"."token_hash" IS 'só o hash é guardado; o link com o token é mostrado uma vez (RN39)';

COMMENT ON COLUMN "convite_propriedade"."revogado_em" IS 'só pode ser revogado enquanto não aceito';

COMMENT ON TABLE "recuperacao_senha" IS 'RF02 (prioridade Baixa).';

COMMENT ON COLUMN "recuperacao_senha"."token_hash" IS 'o token é buscado pelo hash (B3)';

COMMENT ON TABLE "registro_estoque" IS 'RF03 a RF05. Agrupamento de animais que carrega custos, vendas e a decisão de produção. No modo individual, agrupa um único animal. A quantidade vem dos animais ligados (tabela animal). A unicidade de (id, propriedade_id) sustenta a chave estrangeira composta do animal (A4).';

COMMENT ON COLUMN "registro_estoque"."modo_registro" IS 'individual | lote';

COMMENT ON COLUMN "registro_estoque"."origem" IS 'nascimento | aquisicao';

COMMENT ON COLUMN "registro_estoque"."custo_aquisicao" IS 'custo de aquisição na formação (RN16)';

COMMENT ON COLUMN "registro_estoque"."situacao_producao" IS 'em_producao | pronto_para_venda. Só a decisão do produtor (RN02); "parcialmente vendido" e "vendido" são derivados (A3)';

COMMENT ON COLUMN "registro_estoque"."ativo" IS 'inativação em vez de exclusão (RN04)';

COMMENT ON TABLE "pasto" IS 'RF06. Áreas da propriedade onde os animais ficam, cadastradas pelo usuário.';

COMMENT ON COLUMN "pasto"."area_hectares" IS 'opcional';

COMMENT ON TABLE "animal" IS 'RF03, RF06, RN01, RN06. Uma linha por cabeça, criada junto com o registro. Todos os dados individuais são opcionais e não entram nos cálculos.';

COMMENT ON COLUMN "animal"."propriedade_id" IS 'repete a propriedade do registro; a chave composta garante que coincidam (A4). Serve para filtrar e para o brinco único';

COMMENT ON COLUMN "animal"."nome" IS 'opcional';

COMMENT ON COLUMN "animal"."brinco" IS 'opcional; único na propriedade quando informado, inclusive entre animais já vendidos (B5)';

COMMENT ON COLUMN "animal"."sexo" IS 'opcional. macho | femea';

COMMENT ON COLUMN "animal"."raca" IS 'opcional; texto livre';

COMMENT ON COLUMN "animal"."cor" IS 'opcional; texto livre';

COMMENT ON COLUMN "animal"."data_nascimento" IS 'opcional; a idade é calculada';

COMMENT ON COLUMN "animal"."nascimento_estimado" IS 'true quando a data de nascimento é aproximada';

COMMENT ON COLUMN "animal"."peso_inicial_kg" IS 'opcional; os pesos seguintes ficam em pesagem';

COMMENT ON COLUMN "animal"."pasto_id" IS 'pasto atual';

COMMENT ON COLUMN "animal"."movimentacao_entrada_id" IS 'preenchido se o animal entrou depois da formação do registro';

COMMENT ON COLUMN "animal"."venda_id" IS 'preenchido quando o animal é vendido; volta a nulo se a venda for estornada (RN34)';

COMMENT ON COLUMN "animal"."movimentacao_baixa_id" IS 'preenchido quando o animal sai por morte ou descarte; volta a nulo se a baixa for estornada (RN34)';

COMMENT ON TABLE "movimentacao_estoque" IS 'RF07. Evento que altera o saldo sem gerar receita. Entrada cria animais (animal.movimentacao_entrada_id); baixa liga os animais que saíram (animal.movimentacao_baixa_id). A venda tem tabela própria (venda).';

COMMENT ON COLUMN "movimentacao_estoque"."tipo" IS 'entrada | baixa_morte | baixa_descarte';

COMMENT ON COLUMN "movimentacao_estoque"."quantidade" IS 'maior que zero';

COMMENT ON COLUMN "movimentacao_estoque"."custo_aquisicao" IS 'apenas para entradas';

COMMENT ON COLUMN "movimentacao_estoque"."estornada_em" IS 'estorno de baixa (RN34, A1): devolve os animais ao estoque. Entrada não é estornável no MVP';

COMMENT ON TABLE "pesagem" IS 'RF08 (prioridade Baixa). Pesagem de cada animal; pesagem coletiva do lote não está prevista.';

COMMENT ON TABLE "fornecedor" IS 'Base da memória de fornecedor (RF12): a sugestão vem do histórico de custos do fornecedor.';

COMMENT ON TABLE "categoria_custo" IS 'RF11. Categorias livres criadas pelo usuário (ex.: alimentação, sanidade, suplementos, locação).';

COMMENT ON COLUMN "categoria_custo"."sugerida" IS 'criada como sugestão inicial (RF11)';

COMMENT ON TABLE "nota_fiscal" IS 'RF09. Nota em papel digitalizada por foto. Uma nota pode originar vários custos (RN08).';

COMMENT ON COLUMN "nota_fiscal"."numero_documento" IS 'opcional';

COMMENT ON COLUMN "nota_fiscal"."imagem_caminho" IS 'caminho da foto no armazenamento privado (RNF06, RNF14); o arquivo não fica no banco';

COMMENT ON TABLE "recorrencia" IS 'RF13, RN14. Modelo do custo recorrente; gera os custos previstos.';

COMMENT ON COLUMN "recorrencia"."valor" IS 'valor esperado das próximas ocorrências (RN14)';

COMMENT ON COLUMN "recorrencia"."periodicidade" IS 'semanal | quinzenal | mensal | bimestral | trimestral | semestral | anual';

COMMENT ON COLUMN "recorrencia"."proxima_data" IS 'data esperada do próximo lançamento previsto';

COMMENT ON TABLE "custo" IS 'RF10, RF14, RF15. Núcleo do custo acumulado: só custos realizados e não estornados compõem o custo do registro (RN10, RN16).';

COMMENT ON COLUMN "custo"."registro_estoque_id" IS 'sempre vinculado a um registro (RN07)';

COMMENT ON COLUMN "custo"."nota_fiscal_id" IS 'opcional (RN09)';

COMMENT ON COLUMN "custo"."recorrencia_id" IS 'preenchido se o custo veio de uma recorrência';

COMMENT ON COLUMN "custo"."valor" IS 'maior que zero (RN07)';

COMMENT ON COLUMN "custo"."data_compra" IS 'realizado: data da compra; previsto: data esperada';

