COMMENT ON COLUMN "custo"."estornado_em" IS 'estorno em vez de exclusão física (RF16)';

COMMENT ON COLUMN "comprador"."nome" IS 'ex.: frigorífico';

COMMENT ON TABLE "venda" IS 'RF20 a RF24. Venda total ou parcial; um registro pode ter várias vendas, para compradores diferentes. Os animais vendidos são os que apontam para a venda (animal.venda_id).';

COMMENT ON COLUMN "venda"."quantidade_cabecas" IS 'maior que zero, não superior ao saldo (RN03) e igual ao nº de animais ligados à venda (RN32)';

COMMENT ON COLUMN "venda"."peso_vivo_total_kg" IS 'informar este ou arrobas_carcaca_informadas';

COMMENT ON COLUMN "venda"."arrobas_carcaca_informadas" IS 'arrobas de carcaça informadas diretamente (RF21)';

COMMENT ON COLUMN "venda"."rendimento_carcaca_pct" IS 'rendimento aplicado quando a conversão parte do peso vivo; guarda o valor usado na época (RN18)';

COMMENT ON COLUMN "venda"."arrobas_vendidas" IS 'resultado da conversão (RN18)';

COMMENT ON COLUMN "venda"."despesas_venda" IS 'frete, taxas e outras (RN21)';

COMMENT ON COLUMN "venda"."custo_alocado" IS 'RN17: custo médio móvel por cabeça x cabeças vendidas; calculado e gravado pelo serviço de domínio, que recalcula as vendas do registro quando custos, vendas ou baixas mudam. A venda que zera o saldo recebe todo o custo restante';

COMMENT ON COLUMN "venda"."estornada_em" IS 'RF24';

COMMENT ON TABLE "oferta_frigorifico" IS 'RF29 (prioridade Baixa), RN30. Apenas referência; não gera venda.';

COMMENT ON TABLE "cotacao" IS 'RF25, RN26. Cotação registrada manualmente. Se a integração automática vier no futuro, a tabela pode passar a ser compartilhada entre propriedades.';

COMMENT ON COLUMN "cotacao"."praca" IS 'ex.: Minas Gerais';

COMMENT ON TABLE "correcao_justificada" IS 'RN05. Registra correções feitas após a venda total do registro.';

COMMENT ON COLUMN "correcao_justificada"."entidade" IS 'ex.: custo, venda, registro_estoque';

COMMENT ON COLUMN "correcao_justificada"."dados_anteriores" IS 'valores antes da correção';

